class Solution {
public:
    vector<int> smallerNumbersThanCurrent(vector<int>& nums) {
        vector<int> count(101, 0);
        for (int x : nums) ++count[x];
        int seen = 0;
        for (int i = 0; i <= 100; ++i) {
            int c = count[i];
            count[i] = seen;
            seen += c;
        }
        vector<int> result;
        for (int x : nums) result.push_back(count[x]);
        return result;
    }
};
